  create policy "Users can create their own blocks"
  on "public"."blocks"
  as permissive
  for insert
  to public
with check ((auth.uid() = blocker_id));



  create policy "Users can delete their own blocks"
  on "public"."blocks"
  as permissive
  for delete
  to public
using ((auth.uid() = blocker_id));



  create policy "Users can view blocks involving them"
  on "public"."blocks"
  as permissive
  for select
  to public
using (((auth.uid() = blocker_id) OR (auth.uid() = blocked_id)));



  create policy "Users can delete own devices"
  on "public"."devices"
  as permissive
  for delete
  to public
using ((auth.uid() = user_id));



  create policy "users can insert own devices"
  on "public"."devices"
  as permissive
  for insert
  to authenticated
with check ((auth.uid() = user_id));



  create policy "users can read own devices"
  on "public"."devices"
  as permissive
  for select
  to authenticated
using ((auth.uid() = user_id));



  create policy "users can update own devices"
  on "public"."devices"
  as permissive
  for update
  to authenticated
using ((auth.uid() = user_id));



  create policy "Users can delete own drops"
  on "public"."drops"
  as permissive
  for delete
  to public
using (((auth.uid() = sender_id) OR (auth.uid() = receiver_id)));



  create policy "Users can respond to received drops"
  on "public"."drops"
  as permissive
  for update
  to public
using ((auth.uid() = receiver_id));



  create policy "Users can send drops"
  on "public"."drops"
  as permissive
  for insert
  to public
with check ((auth.uid() = sender_id));



  create policy "Users can update their own drops"
  on "public"."drops"
  as permissive
  for update
  to public
using (((auth.uid() = sender_id) OR (auth.uid() = receiver_id)));



  create policy "Users can view their own drops"
  on "public"."drops"
  as permissive
  for select
  to public
using (((auth.uid() = sender_id) OR (auth.uid() = receiver_id)));



  create policy "Users can delete own links"
  on "public"."links"
  as permissive
  for delete
  to public
using (((auth.uid() = user_id_1) OR (auth.uid() = user_id_2)));



  create policy "Users can insert links"
  on "public"."links"
  as permissive
  for insert
  to public
with check (((auth.uid() = user_id_1) OR (auth.uid() = user_id_2)));



  create policy "Users can update their own links."
  on "public"."links"
  as permissive
  for update
  to public
using (((auth.uid() = user_id_1) OR (auth.uid() = user_id_2)))
with check (((auth.uid() = user_id_1) OR (auth.uid() = user_id_2)));



  create policy "Users can view their own links"
  on "public"."links"
  as permissive
  for select
  to public
using (((auth.uid() = user_id_1) OR (auth.uid() = user_id_2)));



  create policy "Users can pin contacts"
  on "public"."pinned_contacts"
  as permissive
  for insert
  to authenticated
with check ((auth.uid() = user_id));



  create policy "Users can unpin contacts"
  on "public"."pinned_contacts"
  as permissive
  for delete
  to authenticated
using ((auth.uid() = user_id));



  create policy "Users can view own pinned contacts"
  on "public"."pinned_contacts"
  as permissive
  for select
  to authenticated
using ((auth.uid() = user_id));



  create policy "Manage tutorial completion"
  on "public"."tutorial_completions"
  as permissive
  for all
  to public
using ((auth.uid() = user_id));



  create policy "Enable insert for users based on user_id"
  on "public"."user_profiles"
  as permissive
  for insert
  to authenticated
with check ((auth.uid() = user_id));



  create policy "Users can delete own profile"
  on "public"."user_profiles"
  as permissive
  for delete
  to public
using ((auth.uid() = user_id));



  create policy "Users can read own profile"
  on "public"."user_profiles"
  as permissive
  for select
  to authenticated
using ((auth.uid() = user_id));



  create policy "allow_update_own_profile"
  on "public"."user_profiles"
  as permissive
  for update
  to authenticated
using ((auth.uid() = user_id))
with check ((auth.uid() = user_id));



  create policy "Users can delete own settings"
  on "public"."user_settings"
  as permissive
  for delete
  to public
using ((auth.uid() = user_id));



  create policy "users can insert own settings"
  on "public"."user_settings"
  as permissive
  for insert
  to authenticated
